import pyomo.environ as pyo

DATA = {
    "products": ["bread", "cookies"],
    "resources": ["mixer", "oven"],
    "profit": {"bread": 5.0, "cookies": 3.0},
    # usage[resource][product] = hours per unit
    "usage": {
        "mixer": {"bread": 1.0, "cookies": 0.5},
        "oven":  {"bread": 3.0, "cookies": 1.0},
    },
    "capacity": {"mixer": 3000.0, "oven": 3000.0},
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.P = pyo.Set(initialize=d["products"])
    model.R = pyo.Set(initialize=d["resources"])

    model.production = pyo.Var(model.P, within=pyo.NonNegativeReals)

    def obj_rule(m):
        return sum(d["profit"][p] * m.production[p] for p in m.P)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    def capacity_rule(m, r):
        return sum(d["usage"][r][p] * m.production[p] for p in m.P) <= d["capacity"][r]

    model.capacity = pyo.Constraint(model.R, rule=capacity_rule)

    return model

import pyomo.environ as pyo

DATA = {
    "products": ["bread", "cookies"],
    "resources": ["mixer", "oven"],
    # hours per unit of product on each resource
    "usage": {
        ("mixer", "bread"): 1.0,
        ("mixer", "cookies"): 0.5,
        ("oven", "bread"): 3.0,
        ("oven", "cookies"): 1.0,
    },
    # annual available hours per resource
    "available": {
        "mixer": 3000.0,
        "oven": 3000.0,
    },
    # profit per unit of product
    "profit": {
        "bread": 5.0,
        "cookies": 3.0,
    },
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.P = pyo.Set(initialize=d["products"])
    model.R = pyo.Set(initialize=d["resources"])

    model.x = pyo.Var(model.P, within=pyo.NonNegativeReals)

    def obj_rule(m):
        return sum(d["profit"][p] * m.x[p] for p in m.P)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    def res_cap_rule(m, r):
        return sum(d["usage"][(r, p)] * m.x[p] for p in m.P) <= d["available"][r]

    model.res_cap = pyo.Constraint(model.R, rule=res_cap_rule)

    return model


